import xarray as xr
import numpy as np
import pandas as pd

def test_dataset_interp_drops_boolean():
    x = np.arange(3)
    ds = xr.Dataset(
        data_vars={
            "a": (["x"], [True, False, True]),
        },
        coords={"x": x},
    )

    new_x = [0.5, 1.5]
    ds_interp = ds.interp(x=new_x)

    print(f"Variables in interpolated dataset: {list(ds_interp.data_vars)}")

    if "a" not in ds_interp.data_vars:
        print("BUG: Variable 'a' (boolean) was silently dropped!")
        exit(1)
    else:
        print("Variable 'a' was preserved.")

if __name__ == "__main__":
    test_dataset_interp_drops_boolean()

